package com.bridge.persistence;
import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.util.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
public class HistoricalAdmissionTest {
 static final ObjectMapper JSON=new ObjectMapper();
 public static FinalMatchEnvelope original(String account){
  var root=(ObjectNode)new LocalManualQuarterRehearsal.Fixture().expired.payload();var m=(ObjectNode)root.path("match");m.put("app_version","0.12.1").put("revision",1).put("score_version",LifetimeStatistics.SCORE_VERSION).put("started_at","2026-11-09T11:33:22Z").put("finished_at","2026-11-09T11:35:48Z").put("planned_deals",1).put("completed_deals",1).put("outcome","SCORED").put("reason","PLANNED_DEALS_COMPLETE").put("winner_team_id","EW").put("ns_total",-1).put("ew_total",5);m.remove(List.of("statistics_rule","match_category","lifetime_rule","room_type","deal_timing_rule"));
  for(int i=0;i<4;i++){var p=(ObjectNode)root.path("participants").get(i);p.put("seat",i).put("team_id",i%2==0?"NS":"EW").put("player_type",i==0?"HUMAN":"BOT").put("control_type",i==0?"HUMAN":"BOT").putNull("guest_id");p.remove(List.of("settlement_control","erased_marker"));if(i==0)p.put("account_id",account);else p.putNull("account_id");}
  var deals=JSON.createArrayNode();var d=(ObjectNode)root.path("completed_deals").get(0).deepCopy();d.put("deal_index",1).put("ns_total",-1).put("ew_total",5);d.remove("elapsed_ms");deals.add(d);root.set("completed_deals",deals);
  return FinalMatchEnvelope.create(m.path("match_id").asText(),1,JSON.convertValue(root,Map.class));
 }
 @Test void explicitAdmissionPreservesSourceAndAddsOneLossMinusOne(){String account=UUID.randomUUID().toString();var old=original(account);var admitted=HistoricalCasualAdmission.migrate(old,UUID.randomUUID().toString());assertEquals(old.payload(),HistoricalCasualAdmission.reconstructed(admitted.payload()));assertNull(old.statisticsCategory());assertEquals("CASUAL",admitted.statisticsCategory());var c=LifetimeStatistics.fromEnvelopes(account,List.of(admitted)).casual();assertEquals(1,c.matches());assertEquals(1,c.losses());assertEquals(-1,c.totalScore());assertFalse(admitted.payload().path("match").has("deal_timing_rule"));assertTrue(LifetimeStatistics.eligibleForRetention(admitted));assertFalse(LifetimeStatistics.eligibleForRetention(old));}
 @Test void redactionKeepsFactsAndCannotSmuggleOtherChanges(){String account=UUID.randomUUID().toString();var admitted=HistoricalCasualAdmission.migrate(original(account),UUID.randomUUID().toString());var root=(ObjectNode)admitted.payload();((ObjectNode)root.path("participants").get(0)).putNull("account_id").put("erased_marker",UUID.randomUUID().toString());HistoricalCasualAdmission.afterAccountErasure(root);var erased=FinalMatchEnvelope.create(admitted.matchId(),2,JSON.convertValue(root,Map.class));assertFalse(erased.canonicalJson().contains(account));assertEquals(admitted.payload().path("historical_admission").path("source_hash"),erased.payload().path("historical_admission").path("source_hash"));assertEquals(0,LifetimeStatistics.fromEnvelopes(account,List.of(erased)).casual().matches());((ObjectNode)root.path("match")).put("started_at","2026-11-08T00:00:00Z");assertThrows(RuntimeException.class,()->HistoricalCasualAdmission.afterAccountErasure(root));}
 @Test void wrongApprovalAndTamperedSourceHashReject(){var old=original(UUID.randomUUID().toString());assertThrows(RuntimeException.class,()->HistoricalCasualAdmission.migrate(old,"not-a-uuid"));var e=HistoricalCasualAdmission.migrate(old,UUID.randomUUID().toString());var r=(ObjectNode)e.payload();((ObjectNode)r.path("historical_admission")).put("source_hash","0".repeat(64));assertThrows(RuntimeException.class,()->FinalMatchEnvelope.create(e.matchId(),2,JSON.convertValue(r,Map.class)));}
}
